def run_agent(request: AgentRunRequest) -> AgentRunStatusResponse:
    """Create an asynchronous agent run and return a run id."""
    return agent_run_service.submit_run(request)

class CodingAgentRuntime:
    """LangGraph runtime for repository-aware coding tasks."""

    def resume(self, run_id: str, approved: bool, feedback: str | None = None):
        """Resume a waiting approval checkpoint."""
        return self._graph.invoke(Command(resume={"approved": approved, "feedback": feedback}))

    def _review_tool_plan(self, state):
        """Pause the run until risky tools are approved."""
        return interrupt(_build_tool_plan_approval_request(state))

class ToolRegistry:
    """Registry that validates tool arguments and audits execution."""

    def execute(self, tool_call: ToolCall, context: ToolExecutionContext | None = None) -> ToolResult:
        validation_error = _validate_arguments(tool_call.arguments, spec.input_schema)
        arguments_summary = summarize_tool_arguments(tool_call.arguments)
        result, output_truncated = _truncate_output(result, max_chars=spec.max_output_chars)
        return ToolResult(arguments_summary=arguments_summary, output_truncated=output_truncated)
